insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A defesa dos interesses e direitos transindividuais previstos na Lei poderá ser exercida, concorrentemente, pelo Ministério Público e por associação de atuação na área, regularmente constituída há pelo menos um ano, nos termos da legislação civil. O requisito da pré-constituição poderá ser dispensado pelo juiz quando entender que não há outra entidade com representatividade adequada para o ajuizamento da demanda coletiva.', '["Defesa de direitos transindividuais por MP e associações.","Associação constituída há pelo menos um ano.","Juiz pode dispensar a pré-constituição se não houver outra entidade adequada."]'::jsonb, '["Legitimação CONCORRENTE."]'::jsonb, 'Associação de mulheres com mais de um ano ajuíza ação coletiva.', '["Assertiva que atribui apenas ao MP a defesa dos direitos transindividuais da lei erra: é concorrente com associações."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-37'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As estatísticas sobre a violência doméstica e familiar contra a mulher serão incluídas nas bases de dados dos órgãos oficiais do Sistema de Justiça e Segurança a fim de subsidiar o sistema nacional de dados e informações relativo às mulheres. As Secretarias de Segurança Pública dos Estados e do Distrito Federal poderão remeter suas informações criminais para a base de dados do Ministério da Justiça.', '["Estatísticas incluídas nas bases do Sistema de Justiça e Segurança.","Subsidiam o sistema nacional de dados sobre mulheres.","Secretarias estaduais podem remeter informações ao Ministério da Justiça."]'::jsonb, '["Remessa das Secretarias estaduais é FACULTATIVA."]'::jsonb, 'A Secretaria estadual de segurança remete seus dados ao Ministério da Justiça.', '["Assertiva que torna obrigatória a remessa de dados das Secretarias de Segurança erra: é faculdade."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-38'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz competente providenciará o registro da medida protetiva de urgência. As medidas protetivas serão, após sua concessão, imediatamente registradas em banco de dados mantido e regulamentado pelo Conselho Nacional de Justiça, garantido o acesso instantâneo do Ministério Público, da Defensoria Pública e dos órgãos de segurança pública e de assistência social, com vistas à fiscalização e à efetividade das medidas.', '["Registro da medida protetiva pelo juiz competente.","Banco de dados mantido e regulamentado pelo CNJ.","Acesso instantâneo do MP, da Defensoria e dos órgãos de segurança e assistência."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.827, de 2019; parágrafo único com redação da Lei nº 14.310, de 2022.","Banco de dados do CNJ."]'::jsonb, 'A medida protetiva é registrada no banco do CNJ, e a polícia consulta de imediato.', '["Assertiva que atribui a manutenção do banco de medidas protetivas ao Ministério Público erra: é do CNJ."]'::jsonb, '[]'::jsonb, '["Art. 12-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-38-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A União, os Estados, o Distrito Federal e os Municípios, no limite de suas competências e nos termos das respectivas leis de diretrizes orçamentárias, poderão estabelecer dotações orçamentárias específicas, em cada exercício financeiro, para a implementação das medidas da Lei. Na implementação, os entes deverão observar, entre as prioridades de alocação de recursos, a aquisição e a manutenção de equipamentos de monitoração eletrônica para agressores e de dispositivos de segurança para as vítimas.', '["Dotações orçamentárias específicas, a cada exercício.","Prioridade: equipamentos de monitoração eletrônica de agressores e dispositivos de segurança para vítimas."]'::jsonb, '["ATUALIZAÇÃO: parágrafo único incluído pela Lei nº 15.383, de 2026."]'::jsonb, 'O Estado prioriza a compra de tornozeleiras eletrônicas para agressores.', '["Assertiva que dispensa a prioridade de recursos para monitoração eletrônica erra."]'::jsonb, '[]'::jsonb, '["Art. 12-D"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-39'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

