select u.id, u.content_sha256, 'As obrigações previstas na Lei não excluem outras decorrentes dos princípios por ela adotados.', '["As obrigações da lei não excluem outras decorrentes dos seus princípios."]'::jsonb, '["Cláusula de abertura."]'::jsonb, 'Obrigação não prevista no texto, mas decorrente dos princípios da lei, também deve ser cumprida.', '["Assertiva que restringe as obrigações da lei às expressamente previstas erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-40'
