insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei será aplicada a todas as situações previstas no seu art. 5º, independentemente da causa ou da motivação dos atos de violência e da condição do ofensor ou da ofendida.', '["Aplica-se a todas as situações do art. 5º.","Independe da causa, da motivação, e da condição do ofensor ou da ofendida."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 14.550, de 2023.","Reforça a aplicação independentemente da motivação."]'::jsonb, 'A lei se aplica à agressão no âmbito doméstico, qualquer que seja o motivo.', '["Assertiva que condiciona a aplicação da lei à motivação do agressor erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-40-a'
