on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei define os crimes de abuso de autoridade cometidos por agente público, servidor ou não, que, no exercício de suas funções ou a pretexto de exercê-las, abuse do poder que lhe tenha sido atribuído. As condutas constituem crime quando praticadas com a finalidade específica de prejudicar outrem ou beneficiar a si mesmo ou a terceiro, ou ainda por mero capricho ou satisfação pessoal. A divergência na interpretação de lei ou na avaliação de fatos e provas não configura abuso de autoridade.', '["Crimes cometidos por agente público no exercício das funções ou a pretexto de exercê-las.","Exige dolo ESPECÍFICO: prejudicar outrem, beneficiar a si ou a terceiro, capricho ou satisfação pessoal.","Divergência de interpretação de lei ou avaliação de provas não é abuso."]'::jsonb, '["Sem a finalidade específica (§1º), não há crime.","A mera divergência jurídica é excluída (§2º)."]'::jsonb, 'Delegado que decreta medida por capricho, para prejudicar um desafeto, pode praticar abuso de autoridade.', '["Assertiva que configura abuso de autoridade pela mera divergência na interpretação da lei erra."]'::jsonb, '[{"termo":"Dolo específico","significado":"Finalidade especial exigida pelo tipo, além da vontade da conduta."}]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É sujeito ativo do crime de abuso de autoridade qualquer agente público, servidor ou não, da administração direta, indireta ou fundacional de qualquer dos Poderes da União, dos Estados, do Distrito Federal, dos Municípios e de Território, compreendendo servidores públicos e militares ou equiparados; membros dos Poderes Legislativo, Executivo e Judiciário; membros do Ministério Público; e membros dos tribunais ou conselhos de contas. Reputa-se agente público todo aquele que exerce, ainda que transitoriamente ou sem remuneração, por eleição, nomeação, designação, contratação ou qualquer outra forma de investidura ou vínculo, mandato, cargo, emprego ou função em órgão ou entidade abrangidos.', '["Sujeito ativo: qualquer agente público, servidor ou não.","Abrange os três Poderes, o MP e os tribunais de contas.","Conceito amplo: ainda que transitório ou sem remuneração."]'::jsonb, '["Rol EXEMPLIFICATIVO (''compreendendo, mas não se limitando a'').","Crime PRÓPRIO: exige a qualidade de agente público."]'::jsonb, 'Mesário voluntário que exerce função pública sem remuneração é agente público para a lei.', '["Assertiva que restringe o sujeito ativo aos servidores efetivos remunerados erra: abrange quem exerce função ainda que transitoriamente ou sem remuneração."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os crimes previstos na Lei são de ação penal pública incondicionada. Será admitida ação privada se a ação penal pública não for intentada no prazo legal, cabendo ao Ministério Público aditar a queixa, repudiá-la e oferecer denúncia substitutiva, intervir em todos os termos do processo, fornecer elementos de prova, interpor recurso e, a todo tempo, no caso de negligência do querelante, retomar a ação como parte principal. A ação privada subsidiária será exercida no prazo de 6 meses, contado da data em que se esgotar o prazo para oferecimento da denúncia.', '["Ação penal pública incondicionada.","Cabe ação privada subsidiária se o MP não agir no prazo.","MP pode aditar, repudiar, denunciar de forma substitutiva e retomar a ação.","Prazo da ação subsidiária: 6 meses após o fim do prazo da denúncia."]'::jsonb, '["Ação privada SUBSIDIÁRIA, só diante da inércia do MP.","Prazo de 6 MESES contados do fim do prazo da denúncia."]'::jsonb, 'O MP não denuncia no prazo, e a vítima ajuíza queixa subsidiária em até 6 meses.', '["Assertiva que torna os crimes de abuso de autoridade de ação penal condicionada à representação erra: são de ação pública incondicionada."]'::jsonb, '[]'::jsonb, '["Art. 29 do CPP"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São efeitos da condenação tornar certa a obrigação de indenizar o dano causado pelo crime, devendo o juiz, a requerimento do ofendido, fixar na sentença o valor mínimo para reparação dos danos; a inabilitação para o exercício de cargo, mandato ou função pública pelo período de 1 a 5 anos; e a perda do cargo, do mandato ou da função pública. Os efeitos dos incisos II e III são condicionados à ocorrência de reincidência em crime de abuso de autoridade e não são automáticos, devendo ser declarados motivadamente na sentença.', '["I: obrigação de indenizar, com valor mínimo fixado na sentença.","II: inabilitação de 1 a 5 anos.","III: perda do cargo, do mandato ou da função.","II e III: só na reincidência e com declaração motivada."]'::jsonb, '["Inabilitação e perda do cargo exigem REINCIDÊNCIA e motivação; NÃO são automáticas."]'::jsonb, 'O condenado reincidente em abuso de autoridade pode perder o cargo, se o juiz declarar motivadamente.', '["Assertiva que torna automática a perda do cargo na primeira condenação por abuso de autoridade erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas restritivas de direitos substitutivas das privativas de liberdade previstas na Lei são a prestação de serviços à comunidade ou a entidades públicas e a suspensão do exercício do cargo, da função ou do mandato, pelo prazo de 1 a 6 meses, com a perda dos vencimentos e das vantagens. O inciso III foi vetado. As penas restritivas de direitos podem ser aplicadas autônoma ou cumulativamente.', '["Prestação de serviços à comunidade ou a entidades públicas.","Suspensão do cargo, da função ou do mandato por 1 a 6 meses, com perda dos vencimentos.","Aplicáveis de forma autônoma ou cumulativa."]'::jsonb, '["Suspensão: 1 a 6 meses, COM perda dos vencimentos."]'::jsonb, 'O juiz substitui a detenção por suspensão do cargo por 3 meses, com perda dos vencimentos.', '["Assertiva que prevê suspensão do cargo sem perda dos vencimentos erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas previstas na Lei serão aplicadas independentemente das sanções de natureza civil ou administrativa cabíveis. As notícias de crimes que descreverem falta funcional serão informadas à autoridade competente com vistas à apuração.', '["Penas aplicadas independentemente de sanções civis e administrativas.","Falta funcional noticiada é informada à autoridade competente."]'::jsonb, '["Independência das esferas penal, civil e administrativa."]'::jsonb, 'O agente condenado criminalmente também responde ao processo disciplinar.', '["Assertiva que impede a sanção administrativa após a condenação criminal por abuso de autoridade erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As responsabilidades civil e administrativa são independentes da criminal, não se podendo mais questionar sobre a existência ou a autoria do fato quando essas questões tenham sido decididas no juízo criminal.', '["Responsabilidades civil e administrativa independem da criminal.","Decidida no juízo criminal a existência ou a autoria do fato, não se pode mais questioná-las."]'::jsonb, '["Independência relativa: o criminal vincula quanto à existência e à autoria."]'::jsonb, 'Reconhecida na sentença penal a autoria do fato, ela não é rediscutida no processo disciplinar.', '["Assertiva que permite rediscutir no juízo cível a autoria já decidida no criminal erra."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Faz coisa julgada em âmbito cível, assim como no administrativo-disciplinar, a sentença penal que reconhecer ter sido o ato praticado em estado de necessidade, em legítima defesa, em estrito cumprimento de dever legal ou no exercício regular de direito.', '["Sentença penal que reconhece excludente de ilicitude faz coisa julgada no cível e no administrativo-disciplinar.","Excludentes: estado de necessidade, legítima defesa, estrito cumprimento de dever legal e exercício regular de direito."]'::jsonb, '["Efeito também na esfera ADMINISTRATIVO-DISCIPLINAR."]'::jsonb, 'Policial absolvido por legítima defesa não pode ser punido disciplinarmente pelo mesmo fato.', '["Assertiva que limita a coisa julgada da absolvição por excludente à esfera cível erra: alcança o administrativo-disciplinar."]'::jsonb, '[]'::jsonb, '["Efeitos da sentença penal absolutória (CPP)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais. Pena: detenção de 1 a 4 anos e multa. Incorre na mesma pena a autoridade judiciária que, dentro de prazo razoável, deixar de relaxar a prisão manifestamente ilegal; de substituir a prisão preventiva por medida cautelar diversa ou de conceder liberdade provisória, quando manifestamente cabível; ou de deferir liminar ou ordem de habeas corpus, quando manifestamente cabível.', '["Decretar privação de liberdade em manifesta desconformidade com a lei.","Detenção de 1 a 4 anos e multa.","Juiz que deixa, em prazo razoável, de relaxar prisão manifestamente ilegal.","Deixar de substituir a preventiva ou conceder liberdade provisória, quando manifestamente cabível.","Deixar de deferir habeas corpus manifestamente cabível."]'::jsonb, '["A ilegalidade deve ser MANIFESTA.","O parágrafo único alcança a omissão da autoridade judiciária."]'::jsonb, 'Juiz que mantém, sem qualquer fundamento, uma prisão manifestamente ilegal pode incorrer no art. 9º.', '["Assertiva que pune a decretação de prisão por mera divergência de interpretação erra: exige manifesta desconformidade."]'::jsonb, '[]'::jsonb, '["Art. 1º, §2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Decretar a condução coercitiva de testemunha ou investigado manifestamente descabida ou sem prévia intimação de comparecimento ao juízo. Pena: detenção de 1 a 4 anos e multa.', '["Condução coercitiva manifestamente descabida.","Ou sem prévia intimação de comparecimento.","Detenção de 1 a 4 anos e multa."]'::jsonb, '["A condução coercitiva do investigado para interrogatório é incompatível com a Constituição (STF)."]'::jsonb, 'Determinar a condução coercitiva do investigado sem intimá-lo antes configura o crime.', '["Assertiva que permite a condução coercitiva sem prévia intimação erra."]'::jsonb, '[]'::jsonb, '["Condução coercitiva (CPP)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar injustificadamente de comunicar prisão em flagrante à autoridade judiciária no prazo legal. Pena: detenção de 6 meses a 2 anos e multa. Incorre na mesma pena quem deixa de comunicar imediatamente a execução de prisão temporária ou preventiva à autoridade que a decretou; deixa de comunicar imediatamente a prisão e o local à família ou à pessoa indicada; deixa de entregar ao preso, em 24 horas, a nota de culpa com o motivo da prisão e os nomes do condutor e das testemunhas; ou prolonga a execução de pena, prisão temporária ou preventiva, medida de segurança ou internação, deixando sem motivo justo e excepcionalíssimo de executar o alvará de soltura imediatamente ou de promover a soltura quando esgotado o prazo.', '["Não comunicar o flagrante ao juiz no prazo legal.","Não comunicar a prisão temporária ou preventiva ao juiz que a decretou.","Não comunicar a prisão à família.","Não entregar a nota de culpa em 24 horas.","Prolongar a prisão ao deixar de cumprir o alvará de soltura."]'::jsonb, '["Nota de culpa: prazo de 24 horas.","Detenção de 6 meses a 2 anos."]'::jsonb, 'Delegado que não entrega ao preso a nota de culpa em 24 horas pratica o crime do art. 12.', '["Assertiva que fixa em dois dias o prazo da nota de culpa no art. 12 erra: são 24 horas."]'::jsonb, '[]'::jsonb, '["Comunicação da prisão (CPP)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constranger o preso ou o detento, mediante violência, grave ameaça ou redução de sua capacidade de resistência, a exibir-se ou ter seu corpo ou parte dele exibido à curiosidade pública; a submeter-se a situação vexatória ou a constrangimento não autorizado em lei; ou a produzir prova contra si mesmo ou contra terceiro. Pena: detenção de 1 a 4 anos e multa, sem prejuízo da pena cominada à violência.', '["Constranger o preso mediante violência, grave ameaça ou redução da capacidade de resistência.","I: exibição à curiosidade pública.","II: situação vexatória.","III: produzir prova contra si ou contra terceiro.","Detenção de 1 a 4 anos e multa, além da pena da violência."]'::jsonb, '["Concurso material com a pena da violência."]'::jsonb, 'Agente que obriga o preso a posar para a imprensa mediante ameaça comete o crime.', '["Assertiva que absorve a pena da violência pelo art. 13 erra: ela é cumulada."]'::jsonb, '[]'::jsonb, '["Art. 38"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constranger a depor, sob ameaça de prisão, pessoa que, em razão de função, ministério, ofício ou profissão, deva guardar segredo ou resguardar sigilo. Pena: detenção de 1 a 4 anos e multa. Incorre na mesma pena quem prossegue com o interrogatório de pessoa que tenha decidido exercer o direito ao silêncio, ou de pessoa que tenha optado por ser assistida por advogado ou defensor público, sem a presença de seu patrono.', '["Constranger a depor, sob ameaça de prisão, quem tem dever de sigilo.","Prosseguir com o interrogatório de quem escolheu o silêncio.","Interrogar quem pediu assistência de advogado, sem a presença dele.","Detenção de 1 a 4 anos e multa."]'::jsonb, '["Protege o direito ao SILÊNCIO e à assistência de advogado."]'::jsonb, 'Delegado que continua a interrogar o preso que optou pelo silêncio comete o crime.', '["Assertiva que permite continuar o interrogatório de quem exerce o direito ao silêncio erra."]'::jsonb, '[]'::jsonb, '["Direito ao silêncio (CPP)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Submeter a vítima de infração penal ou a testemunha de crimes violentos a procedimentos desnecessários, repetitivos ou invasivos, que a leve a reviver, sem estrita necessidade, a situação de violência ou outras situações potencialmente geradoras de sofrimento ou estigmatização. Pena: detenção de 3 meses a 1 ano e multa. Se o agente público permitir que terceiro intimide a vítima de crimes violentos, gerando indevida revitimização, aplica-se a pena aumentada de 2/3. Se o agente público intimidar a vítima, gerando indevida revitimização, aplica-se a pena em dobro.', '["Procedimentos desnecessários, repetitivos ou invasivos contra vítima ou testemunha de crimes violentos.","Detenção de 3 meses a 1 ano e multa.","Permitir que terceiro intimide a vítima: aumento de 2/3.","Agente público que intimida a vítima: pena em dobro."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 14.321, de 2022 (Lei do crime de violência institucional).","Pune a REVITIMIZAÇÃO."]'::jsonb, 'Agente que obriga a vítima de estupro a repetir o relato várias vezes, sem necessidade, comete violência institucional.', '["Assertiva que fixa o aumento de 2/3 para o agente que intimida diretamente a vítima erra: nesse caso a pena é em dobro."]'::jsonb, '[{"termo":"Violência institucional","significado":"Revitimização da vítima por agentes públicos no atendimento."}]'::jsonb, '["Art. 10-A da Lei Maria da Penha"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-15-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de identificar-se ou identificar-se falsamente ao preso por ocasião de sua captura ou quando deva fazê-lo durante sua detenção ou prisão. Pena: detenção de 6 meses a 2 anos e multa. Incorre na mesma pena quem, como responsável por interrogatório em procedimento investigatório de infração penal, deixa de identificar-se ao preso ou atribui a si mesmo falsa identidade, cargo ou função.', '["Não se identificar ou identificar-se falsamente ao preso.","Também o responsável pelo interrogatório que não se identifica ou assume falsa identidade.","Detenção de 6 meses a 2 anos e multa."]'::jsonb, '["Identificação exigida na captura e durante a custódia."]'::jsonb, 'Agente que prende alguém sem se identificar nem informar sua função pratica o crime.', '["Assertiva que dispensa a identificação do responsável pelo interrogatório erra."]'::jsonb, '[]'::jsonb, '["Comunicação da prisão (CPP)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-16'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Submeter o preso a interrogatório policial durante o período de repouso noturno, salvo se capturado em flagrante delito ou se ele, devidamente assistido, consentir em prestar declarações. Pena: detenção de 6 meses a 2 anos e multa.', '["Interrogatório policial no período de repouso noturno.","Exceções: flagrante ou consentimento do preso devidamente assistido.","Detenção de 6 meses a 2 anos e multa."]'::jsonb, '["O flagrante e o consentimento assistido AFASTAM o crime."]'::jsonb, 'Interrogar de madrugada o preso por mandado, sem consentimento assistido, é abuso.', '["Assertiva que proíbe o interrogatório noturno também do preso em flagrante erra: o flagrante é exceção."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-18'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Impedir ou retardar, injustificadamente, o envio de pleito de preso à autoridade judiciária competente para a apreciação da legalidade de sua prisão ou das circunstâncias de sua custódia. Pena: detenção de 1 a 4 anos e multa. Incorre na mesma pena o magistrado que, ciente do impedimento ou da demora, deixa de tomar as providências tendentes a saná-lo ou, não sendo competente para decidir sobre a prisão, deixa de enviar o pedido à autoridade judiciária que o seja.', '["Impedir ou retardar o envio de pleito do preso ao juiz.","Detenção de 1 a 4 anos e multa.","Magistrado ciente que não toma providências.","Magistrado incompetente que não envia o pedido ao competente."]'::jsonb, '["Alcança também o MAGISTRADO omisso."]'::jsonb, 'O diretor do presídio retém o pedido de relaxamento de prisão do preso e não o envia ao juiz.', '["Assertiva que exclui o magistrado do alcance do art. 19 erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-19'
