insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Impedir, sem justa causa, a entrevista pessoal e reservada do preso com seu advogado. Pena: detenção de 6 meses a 2 anos e multa. Incorre na mesma pena quem impede o preso, o réu solto ou o investigado de entrevistar-se pessoal e reservadamente com seu advogado ou defensor, por prazo razoável, antes de audiência judicial, e de sentar-se ao seu lado e com ele comunicar-se durante a audiência, salvo no curso de interrogatório ou no caso de audiência por videoconferência.', '["Impedir, sem justa causa, a entrevista reservada com o advogado.","Detenção de 6 meses a 2 anos e multa.","Também antes da audiência, por prazo razoável.","Comunicação com o advogado durante a audiência, salvo no interrogatório ou na videoconferência."]'::jsonb, '["Entrevista PESSOAL e RESERVADA."]'::jsonb, 'Negar ao preso a conversa reservada com o advogado antes da audiência é crime.', '["Assertiva que permite a presença de agentes durante a entrevista reservada do preso com o advogado erra."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
