insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Manter presos de ambos os sexos na mesma cela ou espaço de confinamento. Pena: detenção de 1 a 4 anos e multa. Incorre na mesma pena quem mantém, na mesma cela, criança ou adolescente na companhia de maior de idade ou em ambiente inadequado, observado o Estatuto da Criança e do Adolescente.', '["Presos de ambos os sexos na mesma cela.","Criança ou adolescente com maior de idade ou em ambiente inadequado.","Detenção de 1 a 4 anos e multa."]'::jsonb, '["Dois núcleos: separação por sexo e proteção de crianças e adolescentes."]'::jsonb, 'Manter homem e mulher presos no mesmo espaço configura o crime.', '["Assertiva que admite a mesma cela para presos de ambos os sexos em situação de emergência, sem crime, erra."]'::jsonb, '[]'::jsonb, '["Local de custódia (CPP)"]'::jsonb, 'under_review', 'claude'
