insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constranger, sob violência ou grave ameaça, funcionário ou empregado de instituição hospitalar pública ou privada a admitir para tratamento pessoa cujo óbito já tenha ocorrido, com o fim de alterar local ou momento de crime, prejudicando sua apuração. Pena: detenção de 1 a 4 anos e multa, além da pena correspondente à violência.', '["Constranger funcionário de hospital a admitir pessoa já morta.","Fim de alterar o local ou o momento do crime.","Detenção de 1 a 4 anos e multa, além da pena da violência."]'::jsonb, '["Cumulação com a pena da violência."]'::jsonb, 'Agente ameaça o médico para que admita como paciente quem já estava morto, modificando o local do crime.', '["Assertiva que dispensa o fim de alterar o local ou o momento do crime erra."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
