insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Requisitar instauração ou instaurar procedimento investigatório de infração penal ou administrativa, em desfavor de alguém, à falta de qualquer indício da prática de crime, de ilícito funcional ou de infração administrativa. Pena: detenção de 6 meses a 2 anos e multa. Não há crime quando se tratar de sindicância ou investigação preliminar sumária, devidamente justificada. O texto remete a ADIs no STF.', '["Requisitar ou instaurar investigação sem QUALQUER indício.","Detenção de 6 meses a 2 anos e multa.","Exclusão: sindicância ou investigação preliminar sumária justificada."]'::jsonb, '["Exige a falta de QUALQUER indício.","Há ações diretas de inconstitucionalidade (ADIs) sobre dispositivos da lei."]'::jsonb, 'Instaurar inquérito contra alguém sem qualquer indício, apenas por perseguição, é crime.', '["Assertiva que pune a instauração de sindicância preliminar justificada erra."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
