select u.id, u.content_sha256, 'Divulgar gravação ou trecho de gravação sem relação com a prova que se pretenda produzir, expondo a intimidade ou a vida privada ou ferindo a honra ou a imagem do investigado ou acusado. Pena: detenção de 1 a 4 anos e multa.', '["Divulgar gravação sem relação com a prova a produzir.","Exposição da intimidade, da vida privada, da honra ou da imagem do investigado ou acusado.","Detenção de 1 a 4 anos e multa."]'::jsonb, '["Vincula-se à ausência de relação com a prova."]'::jsonb, 'Divulgar à imprensa trecho de conversa íntima do investigado, sem relação com os fatos, é crime.', '["Assertiva que pune a divulgação de qualquer gravação, ainda que relacionada à prova, erra."]'::jsonb, '[]'::jsonb, '["Art. 38"]'::jsonb, 'under_review', 'claude'
