insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Demorar demasiada e injustificadamente no exame de processo de que tenha requerido vista em órgão colegiado, com o intuito de procrastinar seu andamento ou retardar o julgamento. Pena: detenção de 6 meses a 2 anos e multa.', '["Demora excessiva e injustificada no pedido de vista em órgão colegiado.","Intuito de procrastinar ou retardar o julgamento.","Detenção de 6 meses a 2 anos e multa."]'::jsonb, '["Pune o pedido de vista usado para procrastinar."]'::jsonb, 'Desembargador pede vista e retém o processo por tempo excessivo para atrasar o julgamento.', '["Assertiva que pune qualquer pedido de vista em órgão colegiado erra: exige demora excessiva e intuito de procrastinar."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
