insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A lei lista, em rol taxativo, os crimes considerados hediondos, tipificados no Código Penal, consumados ou tentados: homicídio praticado em atividade típica de grupo de extermínio (ainda que por um só agente) e homicídio qualificado; lesão corporal dolosa gravíssima e lesão seguida de morte, quando praticadas contra autoridades e agentes de segurança, do sistema prisional, do Judiciário, do Ministério Público e outros, em razão da função, ou nas dependências de instituição de ensino; feminicídio; vicaricídio; roubo circunstanciado pela restrição de liberdade da vítima, pelo emprego de arma de fogo ou de arma de uso proibido ou restrito, e roubo qualificado pelo resultado lesão grave ou morte; extorsão qualificada; extorsão mediante sequestro e na forma qualificada; estupro; estupro de vulnerável; epidemia com resultado morte; falsificação de produto terapêutico ou medicinal; favorecimento da prostituição de criança, adolescente ou vulnerável; furto qualificado pelo emprego de explosivo; induzimento, instigação ou auxílio a suicídio ou automutilação pela internet; sequestro e cárcere privado contra menor de 18 anos; e tráfico de pessoas contra criança ou adolescente. O parágrafo único inclui o genocídio, o porte ou posse ilegal de arma de fogo de uso proibido, o comércio ilegal e o tráfico internacional de armas, a organização criminosa direcionada a crime hediondo ou equiparado, crimes do Código Penal Militar com identidade com os do artigo, crimes do Estatuto da Criança e do Adolescente sobre pornografia infantil e favorecimento da prostituição, e os crimes de domínio social estruturado.', '["Rol TAXATIVO: só é hediondo o que a lei lista (critério legal).","I: homicídio de grupo de extermínio e homicídio qualificado.","I-A: lesão gravíssima ou seguida de morte contra autoridades e agentes de segurança e em escolas.","I-B: feminicídio. I-C: vicaricídio.","II e III: roubo e extorsão qualificados.","IV a VII: extorsão mediante sequestro, estupro, estupro de vulnerável, epidemia com morte, falsificação de medicamentos.","VIII a XII: favorecimento da exploração sexual infantil, furto com explosivo, indução ao suicídio pela internet, sequestro de menor e tráfico de pessoas de criança ou adolescente.","Parágrafo único: genocídio, armas, organização criminosa para crime hediondo, crimes do ECA e domínio social estruturado."]'::jsonb, '["ATUALIZAÇÃO: redação dos incisos I e I-A dada pela Lei nº 15.159, de 2025; incluídos o feminicídio (I-B) e o vicaricídio (I-C) e, no parágrafo único, os crimes de domínio social estruturado.","A lei adota o critério LEGAL (lista), e não o judicial ou misto.","Tentado ou consumado: ambos são hediondos."]'::jsonb, 'O feminicídio, consumado ou tentado, é crime hediondo.', '["Assertiva que considera hediondo qualquer crime praticado com extrema crueldade, ainda que fora do rol legal, erra: o critério é o legal."]'::jsonb, '[{"termo":"Critério legal","significado":"Hediondo é só o crime que a lei lista expressamente."},{"termo":"Vicaricídio","significado":"Homicídio de terceiro (em regra, filho) para atingir a mulher."}]'::jsonb, '["Art. 2º","Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'hediondos' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os crimes hediondos, a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins e o terrorismo são insuscetíveis de anistia, graça e indulto, e de fiança. A pena por esses crimes será cumprida inicialmente em regime fechado. O §2º foi revogado. Em caso de sentença condenatória, o juiz decidirá fundamentadamente se o réu poderá apelar em liberdade. A prisão temporária, nos crimes previstos no artigo, terá o prazo de 30 dias, prorrogável por igual período em caso de extrema e comprovada necessidade.', '["Insuscetíveis de anistia, graça, indulto e fiança.","Regime inicial fechado.","Apelar em liberdade: decisão fundamentada do juiz.","Prisão temporária de 30 dias, prorrogável por igual período."]'::jsonb, '["ATUALIZAÇÃO: o §2º (vedação de progressão) foi revogado e a progressão hoje segue o Código Penal e a LEP, com frações próprias.","Equiparados a hediondos: tortura, tráfico de drogas e terrorismo.","STF: o regime inicial fechado obrigatório foi declarado inconstitucional (o juiz deve fundamentar)."]'::jsonb, 'A prisão temporária por crime hediondo dura 30 dias, prorrogável por mais 30.', '["Assertiva que fixa em 5 dias, prorrogável por mais 5, a prisão temporária nos crimes hediondos erra: são 30 dias, prorrogáveis por igual período."]'::jsonb, '[{"termo":"Crimes equiparados a hediondos","significado":"Tortura, tráfico de drogas e terrorismo, que recebem tratamento similar."}]'::jsonb, '["Art. 1º","Lei de Execução Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'hediondos' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A União manterá estabelecimentos penais de segurança máxima, destinados ao cumprimento de penas impostas a condenados de alta periculosidade, cuja permanência em presídios estaduais ponha em risco a ordem ou a incolumidade pública.', '["União mantém presídios de segurança máxima.","Destino: condenados de alta periculosidade que ponham em risco a ordem ou a incolumidade pública."]'::jsonb, '["Dever da UNIÃO (presídios federais)."]'::jsonb, 'Líder de facção é transferido a presídio federal de segurança máxima.', '["Assertiva que atribui aos Estados a manutenção dos presídios de segurança máxima da lei erra: é da União."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'hediondos' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao art. 83 do Código Penal é acrescido o inciso V (livramento condicional): cumprido mais de dois terços da pena, nos casos de condenação por crime hediondo, prática da tortura, tráfico ilícito de entorpecentes e drogas afins e terrorismo, se o apenado não for reincidente específico em crimes dessa natureza.', '["Livramento condicional após mais de dois terços da pena.","Para hediondos, tortura, tráfico e terrorismo.","Vedado ao reincidente específico."]'::jsonb, '["Hoje o art. 83 do Código Penal tem frações próprias e distingue o reincidente específico; confira a redação vigente."]'::jsonb, 'Condenado primário por crime hediondo só obtém livramento após mais de 2/3 da pena.', '["Assertiva que permite o livramento condicional a qualquer tempo, nos crimes hediondos, erra."]'::jsonb, '[{"termo":"Reincidente específico","significado":"Quem reincide em crime da mesma natureza."}]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'hediondos' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo alterou a redação de dispositivos do Código Penal relativos a crimes depois classificados como hediondos (roubo qualificado, extorsão mediante sequestro, estupro, atentado violento ao pudor, corrupção de menores e epidemia, entre outros), elevando suas penas. Por exemplo, no roubo qualificado pelo resultado, lesão grave tem reclusão de cinco a quinze anos e morte, de vinte a trinta anos; na extorsão mediante sequestro, o caput tem de oito a quinze anos, e as formas qualificadas, de doze a vinte, de dezesseis a vinte e quatro e de vinte e quatro a trinta anos.', '["Alterou penas de crimes do Código Penal depois tratados como hediondos.","Roubo com lesão grave: cinco a quinze anos; com morte: vinte a trinta anos.","Extorsão mediante sequestro: de oito a quinze anos no caput e agravamentos nas formas qualificadas."]'::jsonb, '["Texto histórico: várias penas foram posteriormente alteradas.","A redação atual dos tipos está no Código Penal."]'::jsonb, 'Texto de alteração legislativa; a pena vigente deve ser consultada no Código Penal.', '["Assertiva que aplica hoje, sem conferir o Código Penal, as penas do art. 6º da Lei dos Crimes Hediondos erra."]'::jsonb, '[]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'hediondos' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Trata-se da nova redação dada ao crime de extorsão mediante sequestro: o caput passa a ter pena de reclusão de oito a quinze anos; o §1º (sequestro de longa duração, vítima menor ou idosa, ou crime cometido por bando ou quadrilha), de doze a vinte anos; o §2º (lesão corporal de natureza grave), de dezesseis a vinte e quatro anos; e o §3º (morte), de vinte e quatro a trinta anos.', '["Caput: reclusão de oito a quinze anos.","§1º: doze a vinte anos.","§2º: dezesseis a vinte e quatro anos.","§3º: vinte e quatro a trinta anos."]'::jsonb, '["Texto histórico: confira a redação vigente do art. 159 do Código Penal."]'::jsonb, 'Extorsão mediante sequestro com resultado morte: reclusão de vinte e quatro a trinta anos.', '["Assertiva que fixa em vinte a trinta anos a pena da extorsão mediante sequestro com morte erra: é de vinte e quatro a trinta."]'::jsonb, '[]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
