insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Será de três a seis anos de reclusão a pena da associação criminosa prevista no art. 288 do Código Penal, quando se tratar de crimes hediondos, prática da tortura, tráfico ilícito de entorpecentes e drogas afins ou terrorismo. O participante e o associado que denunciar à autoridade o bando ou quadrilha, possibilitando seu desmantelamento, terá a pena reduzida de um a dois terços.', '["Associação para crimes hediondos ou equiparados: reclusão de 3 a 6 anos.","Delação que possibilite o desmantelamento do bando: redução de 1/3 a 2/3."]'::jsonb, '["A pena do art. 288 comum é menor; aqui é de 3 a 6 anos.","A delação deve possibilitar o DESMANTELAMENTO."]'::jsonb, 'Quem integra um bando para praticar crimes hediondos responde com pena de 3 a 6 anos.', '["Assertiva que fixa em 1 a 3 anos a pena da associação para crimes hediondos erra: é de 3 a 6 anos."]'::jsonb, '[]'::jsonb, '["Associação criminosa (Código Penal)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'hediondos' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas fixadas no art. 6º para os crimes de roubo qualificado, extorsão qualificada, extorsão mediante sequestro, estupro e atentado violento ao pudor (este, em combinação com o art. 223) são acrescidas de metade, respeitado o limite superior de trinta anos de reclusão, estando a vítima em qualquer das hipóteses do art. 224 do Código Penal (presunção de violência).', '["Acréscimo de metade às penas dos crimes sexuais e patrimoniais violentos.","Limite superior de trinta anos de reclusão.","Vítima nas hipóteses de presunção de violência do art. 224 do CP."]'::jsonb, '["Dispositivo histórico: o art. 224 do Código Penal foi revogado em 2009."]'::jsonb, 'Texto histórico, sem aplicação prática atual.', '["Assertiva que aplica hoje o acréscimo de metade do art. 9º erra, porque o art. 224 foi revogado."]'::jsonb, '[]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'hediondos' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 35 da antiga Lei de Tóxicos (lei antiga de tóxicos) passou a vigorar acrescido de parágrafo único: os prazos procedimentais do capítulo serão contados em dobro quando se tratar dos crimes dos arts. 12, 13 e 14 daquela lei. A lei antiga foi revogada pela Lei de Drogas atual.', '["Prazos procedimentais em dobro nos crimes de tráfico da lei antiga."]'::jsonb, '["Dispositivo histórico: a lei antiga de tóxicos, foi revogada."]'::jsonb, 'Texto histórico, sem aplicação prática atual.', '["Assertiva que aplica hoje a contagem em dobro dos prazos da lei antiga de tóxicos erra."]'::jsonb, '[]'::jsonb, '["Lei de Drogas"]'::jsonb, 'under_review', 'claude'
